calc:
cat > /home/learner/aso/f21/calc.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 3 ] || { echo 'uso: calc.sh A OP B' >&2; exit 1; }
a=$1 op=$2 b=$3
entero='^-?[0-9]+$'
[[ $a =~ $entero && $b =~ $entero ]] || { echo 'error: los operandos deben ser enteros' >&2; exit 2; }
case $op in
    +) r=$(( a + b )) ;;
    -) let r=a-b ;;
    x) (( r = a * b )) ;;
    /|%)
        (( b == 0 )) && { echo 'error: división por cero' >&2; exit 4; }
        if [ "$op" = / ]; then r=$(( a / b )); else r=$(( a % b )); fi ;;
    *) echo 'error: operador no válido' >&2; exit 3 ;;
esac
echo "$r"
SOLUCION
chmod 755 /home/learner/aso/f21/calc.sh
chown learner:learner /home/learner/aso/f21/calc.sh

recuento:
cat > /home/learner/aso/f21/recuento.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 1 ] || { echo 'uso: recuento.sh FICHERO' >&2; exit 1; }
f=$1
[ -f "$f" ] && [ -r "$f" ] || { echo "error: no se puede leer $f" >&2; exit 2; }
echo "$f: $(wc -l < "$f") líneas, $(wc -w < "$f") palabras, $(wc -c < "$f") bytes"
SOLUCION
chmod 755 /home/learner/aso/f21/recuento.sh
chown learner:learner /home/learner/aso/f21/recuento.sh

shell-de:
cat > /home/learner/aso/f21/shell-de.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 1 ] || { echo 'uso: shell-de.sh USUARIO' >&2; exit 1; }
linea=$(getent passwd "$1") || { echo "error: $1 no existe" >&2; exit 2; }
shell=${linea##*:}
case $shell in
    */bash) echo "$1: bash" ;;
    */sh) echo "$1: sh" ;;
    *nologin|*/false) echo "$1: sin acceso interactivo" ;;
    *) echo "$1: otro ($shell)" ;;
esac
SOLUCION
chmod 755 /home/learner/aso/f21/shell-de.sh
chown learner:learner /home/learner/aso/f21/shell-de.sh

maximo:
cat > /home/learner/aso/f21/maximo.sh <<'SOLUCION'
#!/bin/bash
es_entero() {
    [[ $1 =~ ^-?[0-9]+$ ]] && return 0
    return 1
}
maximo() {
    local m=$1 v
    shift
    for v in "$@"; do
        (( v > m )) && m=$v
    done
    echo "$m"
}
[ $# -ge 1 ] || { echo 'uso: maximo.sh N...' >&2; exit 1; }
for v in "$@"; do
    es_entero "$v" || { echo "error: $v no es un entero" >&2; exit 2; }
done
maximo "$@"
SOLUCION
chmod 755 /home/learner/aso/f21/maximo.sh
chown learner:learner /home/learner/aso/f21/maximo.sh
